const INSTR={"supino":[["Deite no banco com os pés firmes no chão e os olhos alinhados abaixo da barra (ou com os halteres apoiados nas coxas).","Junte as escápulas, abra o peito e mantenha uma leve curva na lombar.","Segure com as mãos um pouco mais abertas que os ombros e tire o peso do suporte com os braços estendidos.","Desça devagar até a altura do meio do peito, com os cotovelos a cerca de 45° do tronco.","Empurre de volta até estender os braços, soltando o ar na subida."],["Não deixe os cotovelos abrirem a 90° do corpo: sobrecarrega o ombro.","Mantenha os glúteos no banco durante toda a série."]],"supinoinc":[["Ajuste o banco entre 30° e 45° e deite com os pés firmes no chão.","Junte as escápulas e segure o peso um pouco mais aberto que os ombros.","Desça de forma controlada até a parte de cima do peito, logo abaixo da clavícula.","Empurre para cima e levemente para trás até estender os braços."],["Inclinação acima de 45° transfere o trabalho para os ombros.","Não tire a cabeça nem os glúteos do banco."]],"supinodec":[["Prenda as pernas no apoio do banco declinado e deite com a cabeça mais baixa que o quadril.","Segure o peso com as mãos um pouco mais abertas que os ombros.","Desça até a parte de baixo do peito, com os cotovelos a cerca de 45°.","Empurre de volta até estender os braços."],["Peça ajuda para tirar e devolver a barra no suporte.","Controle a descida: o declínio facilita perder a trajetória."]],"supinomaq":[["Ajuste o banco para que as manoplas fiquem na altura do meio do peito.","Sente com as costas apoiadas e as escápulas juntas.","Empurre as manoplas para frente até quase estender os cotovelos.","Volte devagar até sentir o alongamento do peito, sem deixar o peso encostar."],["Não tire as costas do encosto para empurrar.","Mantenha os punhos alinhados com os antebraços."]],"supinofechado":[["Deite no banco e segure a barra com as mãos na largura dos ombros.","Mantenha os cotovelos próximos ao corpo durante toda a descida.","Desça até a parte de baixo do peito.","Empurre de volta estendendo totalmente os cotovelos, focando no tríceps."],["Mãos coladas demais forçam os punhos; a largura dos ombros basta."]],"supinochao":[["Deite no chão com os joelhos dobrados e o peso acima do peito.","Desça até os tríceps encostarem no chão, com os cotovelos a cerca de 45°.","Faça uma pausa curta no chão e empurre até estender os braços."],["O chão limita a amplitude e protege os ombros; não quique os cotovelos."]],"crucifixo":[["Deite no banco segurando os halteres acima do peito, palmas viradas uma para a outra.","Mantenha os cotovelos levemente dobrados e fixos durante todo o movimento.","Abra os braços em arco até sentir o alongamento do peito, na altura dos ombros.","Feche os braços pelo mesmo arco, como se abraçasse um tronco de árvore."],["Não desça além da linha dos ombros.","Se os cotovelos dobram e esticam, virou supino: reduza a carga."]],"crossover":[["Ajuste as polias no alto e segure uma alça em cada mão.","Dê um passo à frente, incline levemente o tronco e mantenha os cotovelos semiflexionados.","Puxe as alças para baixo e para frente em arco até as mãos se encontrarem na frente do quadril.","Volte devagar até sentir o alongamento do peito."],["Os braços giram no ombro; os cotovelos não devem mudar de ângulo."]],"crossoverbaixo":[["Ajuste as polias na parte de baixo e segure as alças com as palmas para cima.","Com os cotovelos levemente dobrados, puxe as alças para cima e para dentro em arco.","Encontre as mãos na altura do queixo, contraindo a parte de cima do peito.","Volte devagar à posição inicial."],["Mantenha o tronco parado; não use impulso das pernas."]],"peckdeck":[["Ajuste o assento para que as manoplas fiquem na altura do peito.","Sente com as costas apoiadas e segure as manoplas com os cotovelos levemente dobrados.","Feche os braços à frente do corpo, contraindo o peito por um segundo.","Volte devagar até sentir o alongamento, sem deixar o peso bater."],["Não deixe os ombros subirem em direção às orelhas."]],"flexao":[["Apoie as mãos no chão um pouco mais abertas que os ombros e estenda as pernas.","Mantenha o corpo reto da cabeça aos calcanhares, contraindo abdômen e glúteos.","Desça até o peito quase encostar no chão, cotovelos a cerca de 45°.","Empurre o chão até estender os braços."],["Não deixe o quadril cair nem subir demais.","Se não completar as repetições, apoie os joelhos."]],"paralelas":[["Segure as barras paralelas e suba com os braços estendidos.","Incline o tronco à frente e cruze as pernas atrás.","Desça dobrando os cotovelos até os ombros ficarem um pouco abaixo dos cotovelos.","Empurre de volta até estender os braços."],["Tronco inclinado foca no peito; tronco reto foca no tríceps.","Pare a descida se sentir dor na frente do ombro."]],"paralelastri":[["Segure as barras paralelas e suba com os braços estendidos.","Mantenha o tronco o mais reto possível e os cotovelos apontando para trás.","Desça até os cotovelos formarem cerca de 90°.","Empurre de volta estendendo totalmente os cotovelos."],["Evite abrir os cotovelos para os lados."]],"pullover":[["Deite atravessado ou ao longo do banco segurando um halter com as duas mãos acima do peito.","Com os cotovelos levemente dobrados, leve o peso para trás da cabeça em arco.","Desça até sentir o alongamento de dorsais e peito.","Traga o peso de volta pelo mesmo arco até acima do peito."],["Não dobre e estique os cotovelos durante o movimento."]],"svend":[["Fique em pé segurando uma ou duas anilhas pressionadas entre as palmas, na altura do peito.","Aperte as anilhas com força, contraindo o peito.","Estenda os braços à frente mantendo a pressão.","Volte ao peito sem soltar a pressão."],["O ganho vem do aperto constante, não da carga."]],"puxada":[["Sente na máquina e ajuste o apoio das coxas.","Segure a barra na pegada indicada, com os braços estendidos.","Puxe a barra até a parte de cima do peito, levando os cotovelos para baixo e para trás.","Contraia as costas por um instante e suba devagar até estender os braços."],["Não jogue o tronco para trás para puxar.","Evite puxar a barra por trás da nuca."]],"barrafixa":[["Segure a barra na pegada indicada e fique pendurado com os braços estendidos.","Contraia o abdômen e puxe as escápulas para baixo antes de dobrar os cotovelos.","Puxe o corpo até o queixo passar da barra.","Desça de forma controlada até estender os braços."],["Evite balançar o corpo para subir.","Na versão assistida, quanto mais peso de assistência, mais fácil fica."]],"remadacurvada":[["Segure o peso com as mãos na largura dos ombros e incline o tronco à frente, coluna neutra.","Dobre levemente os joelhos e deixe os braços estendidos abaixo dos ombros.","Puxe o peso em direção ao umbigo, levando os cotovelos para trás.","Junte as escápulas no topo e desça devagar."],["Não arredonde a lombar.","Não levante o tronco a cada repetição para ajudar."]],"remadaunilateral":[["Apoie um joelho e uma mão no banco, com a coluna paralela ao chão.","Segure o halter com a outra mão e o braço estendido.","Puxe o halter em direção ao quadril, mantendo o cotovelo próximo ao corpo.","Desça devagar até estender o braço. Complete as repetições e troque de lado."],["Não gire o tronco para subir o peso."]],"remadasentada":[["Sente com os pés apoiados e os joelhos levemente dobrados.","Segure a pegada com os braços estendidos e o tronco ereto.","Puxe em direção ao abdômen, levando os cotovelos para trás e juntando as escápulas.","Volte devagar até estender os braços, sem inclinar o tronco à frente."],["O tronco fica parado; quem puxa são as costas e os braços."]],"remadamaq":[["Ajuste o assento para que as manoplas fiquem na altura do meio do peito.","Apoie o peito no encosto e segure as manoplas.","Puxe levando os cotovelos para trás e juntando as escápulas.","Volte devagar até estender os braços."],["Na versão iso-lateral, dá para treinar um lado de cada vez."]],"cavalinho":[["Posicione-se sobre a barra T com os pés firmes e os joelhos levemente dobrados.","Incline o tronco à frente com a coluna neutra e segure a pegada.","Puxe o peso em direção ao peito, levando os cotovelos para trás.","Desça devagar até estender os braços."],["Não arredonde as costas; o quadril fica parado."]],"remadainvertida":[["Deite sob uma barra fixa baixa (ou argolas) e segure-a com os braços estendidos.","Mantenha o corpo reto, apoiado nos calcanhares.","Puxe o peito até a barra, juntando as escápulas.","Desça devagar até estender os braços."],["Quanto mais horizontal o corpo, mais difícil."]],"retaestendida":[["Fique em pé de frente para a polia alta e segure a barra ou corda com os braços estendidos.","Incline levemente o tronco à frente.","Com os cotovelos quase retos, puxe a barra até a altura das coxas.","Volte devagar até os braços ficarem acima da cabeça."],["Os cotovelos não devem dobrar: o movimento é dos ombros."]],"facepull":[["Ajuste a polia na altura do rosto e segure a corda com as palmas para baixo.","Dê um passo para trás com os braços estendidos.","Puxe a corda em direção ao rosto, abrindo as mãos e levando os cotovelos para fora e para cima.","Segure um instante e volte devagar."],["Use carga leve e foque na parte de trás dos ombros."]],"crucinv":[["Na máquina, sente de frente para o encosto; com halteres, incline o tronco à frente.","Segure com os cotovelos levemente dobrados.","Abra os braços para os lados até a linha dos ombros, juntando as escápulas.","Volte devagar à posição inicial."],["Não use impulso do tronco.","Foque na parte de trás dos ombros e no meio das costas."]],"terra":[["Fique com os pés na largura do quadril e a barra sobre o meio dos pés.","Dobre quadril e joelhos e segure a barra por fora das pernas, coluna neutra e peito aberto.","Empurre o chão com os pés e estenda quadril e joelhos ao mesmo tempo, mantendo a barra colada às pernas.","Termine em pé com glúteos contraídos e desça pelo mesmo caminho."],["Nunca arredonde a lombar.","A barra deve subir encostando nas canelas e nas coxas."]],"stiff":[["Fique em pé segurando o peso à frente das coxas, joelhos levemente dobrados.","Empurre o quadril para trás e desça o peso rente às pernas, coluna neutra.","Desça até sentir o alongamento dos posteriores de coxa (geralmente na altura da canela).","Volte contraindo glúteos e posteriores."],["O movimento é do quadril, não da coluna.","Não trave os joelhos."]],"goodmorning":[["Apoie a barra nas costas, como no agachamento, com os joelhos levemente dobrados.","Empurre o quadril para trás e incline o tronco à frente com a coluna neutra.","Desça até o tronco ficar quase paralelo ao chão ou até o limite dos posteriores.","Volte à posição em pé contraindo glúteos."],["Comece com carga leve; a técnica importa mais que o peso."]],"hiperext":[["Ajuste o aparelho para que a borda fique logo abaixo do quadril e prenda os pés.","Cruze os braços no peito (ou segure uma anilha para mais carga).","Desça o tronco dobrando no quadril, coluna neutra.","Suba até o corpo ficar em linha reta, sem hiperestender as costas."],["Não ultrapasse a linha do corpo na subida."]],"superman":[["Deite de bruços com braços estendidos à frente.","Levante braços, peito e pernas do chão ao mesmo tempo.","Segure por 1 a 2 segundos e desça devagar."],["Olhe para o chão para manter o pescoço neutro."]],"rackpull":[["Ajuste os pinos do rack na altura dos joelhos e coloque a barra sobre eles.","Segure a barra com a coluna neutra e o peito aberto.","Estenda o quadril até ficar em pé, puxando os ombros para trás.","Desça a barra de volta aos pinos de forma controlada."],["Permite usar mais carga que o terra completo; mantenha a técnica."]],"encolhimento":[["Fique em pé segurando o peso com os braços estendidos ao lado ou à frente do corpo.","Eleve os ombros em direção às orelhas o máximo possível.","Segure um segundo no topo.","Desça devagar."],["Não gire os ombros; o movimento é só para cima e para baixo."]],"desenv":[["Sente ou fique em pé com o peso na altura dos ombros, cotovelos à frente do corpo.","Contraia o abdômen e mantenha a lombar neutra.","Empurre o peso para cima até estender os braços acima da cabeça.","Desça de forma controlada até a altura do queixo."],["Não arqueie a lombar para empurrar.","A barra passa perto do rosto, não à frente dele."]],"arnold":[["Sente com os halteres na frente do rosto, palmas viradas para você.","Empurre para cima girando os punhos até as palmas ficarem para a frente.","Estenda os braços acima da cabeça.","Desça fazendo o giro inverso."],["Faça o giro de forma suave e contínua."]],"elevlat":[["Fique em pé com o peso ao lado do corpo e os cotovelos levemente dobrados.","Eleve os braços para os lados até a altura dos ombros.","Mantenha os cotovelos um pouco acima dos punhos no topo.","Desça devagar."],["Não balance o tronco.","Pare na altura dos ombros; subir mais trabalha o trapézio."]],"elevfront":[["Fique em pé segurando o peso à frente das coxas.","Eleve os braços à frente até a altura dos ombros, cotovelos quase retos.","Desça devagar."],["Não use impulso do quadril."]],"remadaalta":[["Fique em pé segurando o peso à frente das coxas, mãos na largura dos ombros.","Puxe o peso para cima rente ao corpo, levando os cotovelos para cima e para fora.","Suba até a altura do peito, sem passar os cotovelos muito acima dos ombros.","Desça devagar."],["Pegada muito fechada pode incomodar os ombros."]],"pullapart":[["Segure o elástico à frente do peito com os braços estendidos.","Abra os braços para os lados, esticando o elástico até ele encostar no peito.","Volte devagar."],["Mantenha os ombros baixos e as escápulas juntas no final."]],"yraise":[["Deite de bruços em um banco inclinado ou incline o tronco à frente.","Com os polegares para cima, eleve os braços em diagonal formando um Y.","Segure um instante no topo e desça devagar."],["Use carga leve; o foco é a estabilidade do ombro."]],"rosca":[["Fique em pé com o peso nas mãos, palmas para a frente e cotovelos colados ao corpo.","Dobre os cotovelos e suba o peso até a altura dos ombros.","Contraia o bíceps por um instante.","Desça devagar até estender os braços."],["Não balance o tronco.","Os cotovelos não devem ir para a frente."]],"rosca21":[["Faça 7 repetições da posição estendida até a metade do movimento (cotovelos a 90°).","Em seguida, 7 repetições da metade até o topo.","Termine com 7 repetições completas, da extensão total até o topo."],["Use carga menor que na rosca comum: são 21 repetições seguidas."]],"martelo":[["Fique em pé com os halteres ao lado do corpo, palmas viradas para as coxas.","Mantenha os cotovelos colados ao corpo.","Dobre os cotovelos e suba o peso mantendo as palmas para dentro.","Desça devagar."],["A pegada neutra trabalha mais o braquial e o antebraço."]],"scott":[["Ajuste o banco Scott para que as axilas encostem no topo do apoio.","Apoie a parte de trás dos braços no apoio e segure o peso com as palmas para cima.","Suba o peso até os antebraços ficarem quase verticais.","Desça devagar até quase estender os cotovelos."],["Não estenda completamente com carga pesada: protege o cotovelo."]],"concentrada":[["Sente no banco com as pernas afastadas e apoie o cotovelo na parte interna da coxa.","Deixe o halter pendurado com o braço estendido.","Suba o peso em direção ao ombro, contraindo o bíceps.","Desça devagar. Complete as repetições e troque de braço."],["O braço de apoio fica parado; só o antebraço se move."]],"roscainc":[["Ajuste o banco entre 45° e 60° e sente com as costas apoiadas.","Deixe os braços pendurados com os halteres, palmas para a frente.","Dobre os cotovelos sem tirá-los da posição.","Desça devagar até estender totalmente."],["A posição alongada aumenta o estímulo no bíceps; use carga menor."]],"bayesian":[["Fique de costas para a polia baixa segurando a alça com um braço.","Dê um passo à frente para que o braço fique estendido atrás do corpo.","Dobre o cotovelo trazendo a mão em direção ao ombro, sem mover o braço.","Volte devagar. Troque de lado ao final."],["O estímulo é maior na parte alongada do movimento."]],"roscainv":[["Fique em pé segurando o peso com as palmas para baixo.","Mantenha os cotovelos colados ao corpo.","Suba o peso até a altura dos ombros.","Desça devagar."],["Trabalha antebraço e braquial; use carga menor que na rosca comum."]],"spider":[["Deite de bruços em um banco inclinado com os braços pendurados à frente.","Segure o peso com as palmas para cima.","Dobre os cotovelos subindo o peso sem mover os braços.","Desça devagar até estender."],["A posição elimina o impulso do tronco."]],"arrasto":[["Fique em pé segurando a barra à frente das coxas.","Suba a barra arrastando-a rente ao corpo, levando os cotovelos para trás.","Suba até o meio do peito e desça pelo mesmo caminho."],["Os cotovelos vão para trás, não para a frente."]],"zottman":[["Suba os halteres como na rosca comum, palmas para cima.","No topo, gire os punhos até as palmas ficarem para baixo.","Desça devagar com as palmas para baixo.","Gire de volta embaixo e repita."],["Combina bíceps na subida e antebraço na descida."]],"punho":[["Sente com os antebraços apoiados nas coxas ou em um banco, punhos para fora.","Segure o peso com as palmas para cima.","Dobre os punhos subindo o peso o máximo possível.","Desça devagar, deixando o peso rolar até os dedos."],["Use amplitude completa e carga moderada."]],"punhoext":[["Sente com os antebraços apoiados, palmas para baixo e punhos para fora.","Estenda os punhos levantando o dorso das mãos.","Desça devagar."],["Carga bem menor que na flexão de punho."]],"rolo":[["Segure o rolo de antebraço com os braços estendidos à frente.","Gire os punhos alternadamente para enrolar a corda até o peso subir.","Desenrole devagar até o peso descer."],["Mantenha os braços na altura dos ombros."]],"pulley":[["Fique de frente para a polia alta e segure a barra ou corda.","Cole os cotovelos ao lado do corpo.","Empurre para baixo até estender totalmente os cotovelos.","Volte devagar até os antebraços ficarem um pouco acima da horizontal."],["Os cotovelos não saem do lugar.","Com corda, abra as mãos no final do movimento."]],"testa":[["Deite no banco segurando o peso acima do peito, braços estendidos.","Mantenha os braços parados e dobre os cotovelos, descendo o peso em direção à testa.","Desça até os cotovelos formarem cerca de 90°.","Estenda os cotovelos voltando à posição inicial."],["Os cotovelos apontam para o teto, sem abrir para os lados."]],"frances":[["Sente ou fique em pé segurando o peso acima da cabeça com os braços estendidos.","Mantenha os cotovelos apontando para cima, próximos à cabeça.","Desça o peso atrás da cabeça dobrando os cotovelos.","Estenda os cotovelos voltando ao topo."],["Contraia o abdômen para não arquear a lombar."]],"coice":[["Incline o tronco à frente, apoiando uma mão no banco se precisar.","Cole o braço ao lado do corpo com o cotovelo dobrado a 90°.","Estenda o cotovelo levando o peso para trás.","Volte devagar até 90°."],["Só o antebraço se move."]],"tricmaq":[["Ajuste o assento para que os cotovelos fiquem alinhados ao eixo da máquina.","Segure as manoplas com os cotovelos dobrados.","Estenda os cotovelos até o final do movimento.","Volte devagar."],["Não use o tronco para empurrar."]],"banco":[["Sente na borda de um banco e apoie as mãos ao lado do quadril.","Tire o quadril do banco com as pernas estendidas ou dobradas.","Desça dobrando os cotovelos até cerca de 90°.","Empurre de volta estendendo os braços."],["Mantenha as costas perto do banco.","Pernas dobradas deixam mais fácil."]],"jmpress":[["Deite no banco com a barra acima do peito, pegada na largura dos ombros.","Desça a barra em direção ao queixo dobrando os cotovelos, que avançam levemente.","Pare quando os antebraços encostarem nos bíceps.","Empurre de volta estendendo os cotovelos."],["Mistura supino fechado com tríceps testa; use carga moderada."]],"tate":[["Deite no banco com os halteres acima do peito e os cotovelos apontando para fora.","Dobre os cotovelos descendo os halteres até encostarem no peito.","Estenda os cotovelos voltando ao topo."],["Mantenha os braços parados; só os cotovelos dobram."]],"agachamento":[["Posicione a barra sobre o trapézio (ou segure o peso) e fique com os pés na largura dos ombros.","Contraia o abdômen e mantenha o peito aberto.","Desça empurrando o quadril para trás e dobrando os joelhos, que acompanham a direção dos pés.","Desça até as coxas ficarem pelo menos paralelas ao chão.","Suba empurrando o chão com o pé inteiro."],["Os joelhos não devem cair para dentro.","Mantenha os calcanhares no chão."]],"agachfront":[["Apoie a barra na frente dos ombros, cotovelos altos e apontando para a frente.","Fique com os pés na largura dos ombros.","Desça mantendo o tronco o mais vertical possível.","Suba empurrando o chão, sem deixar os cotovelos caírem."],["Exige mobilidade de punho e tornozelo; aqueça bem."]],"goblet":[["Segure o peso junto ao peito com as duas mãos.","Fique com os pés um pouco mais abertos que os ombros.","Desça entre as pernas mantendo o tronco ereto e os cotovelos por dentro dos joelhos.","Suba empurrando o chão."],["Ótimo para aprender a técnica do agachamento."]],"hack":[["Apoie as costas e os ombros no encosto da máquina.","Posicione os pés na plataforma na largura dos ombros.","Destrave e desça dobrando os joelhos até cerca de 90° ou mais.","Empurre a plataforma voltando ao início, sem travar os joelhos."],["Pés mais baixos focam no quadríceps; mais altos, em glúteos."]],"legpress":[["Sente com as costas apoiadas e os pés na plataforma, na largura dos ombros.","Destrave a plataforma.","Desça dobrando os joelhos até cerca de 90°, sem tirar a lombar do encosto.","Empurre de volta sem travar os joelhos no final."],["Não deixe o quadril descolar do banco.","Joelhos alinhados com a ponta dos pés."]],"extensora":[["Ajuste o encosto para que os joelhos fiquem alinhados ao eixo da máquina.","Posicione o apoio logo acima dos tornozelos.","Estenda os joelhos até as pernas ficarem retas.","Segure um instante e desça devagar."],["Segure nas alças laterais para não levantar o quadril."]],"flexora":[["Ajuste a máquina para que os joelhos fiquem alinhados ao eixo de rotação.","Posicione o apoio logo acima dos calcanhares.","Dobre os joelhos trazendo os calcanhares em direção aos glúteos.","Volte devagar até quase estender."],["Não levante o quadril durante a subida."]],"bulgaro":[["Fique à frente de um banco e apoie o peito do pé de trás sobre ele.","Segure o peso e posicione o pé da frente a uma passada do banco.","Desça dobrando o joelho da frente até a coxa ficar paralela ao chão.","Suba empurrando com o pé da frente. Troque de perna ao final."],["Tronco levemente inclinado foca mais nos glúteos."]],"afundo":[["Fique em pé segurando o peso, pés na largura do quadril.","Dê um passo à frente e desça até os dois joelhos formarem cerca de 90°.","O joelho de trás quase encosta no chão.","Empurre com o pé da frente para voltar. Alterne as pernas."],["Mantenha o tronco ereto.","O joelho da frente acompanha a ponta do pé."]],"afundoreverso":[["Fique em pé segurando o peso.","Dê um passo para trás e desça até os joelhos formarem cerca de 90°.","Empurre com o pé da frente para voltar. Alterne as pernas."],["Mais fácil para os joelhos que o afundo à frente."]],"passada":[["Fique em pé segurando o peso.","Dê um passo à frente e desça até os joelhos formarem cerca de 90°.","Empurre e já leve a perna de trás para a frente, iniciando o próximo passo.","Continue caminhando pelo espaço."],["Passos longos focam em glúteos; curtos, em quadríceps."]],"afundolat":[["Fique com os pés afastados bem além da largura dos ombros.","Desloque o peso para um lado, dobrando esse joelho e mantendo a outra perna estendida.","Volte ao centro e repita para o outro lado."],["Mantenha o pé da perna dobrada inteiro no chão."]],"stepup":[["Fique de frente para um banco ou caixa segurando o peso.","Apoie um pé inteiro sobre o banco.","Suba empurrando com essa perna até ficar em pé sobre o banco.","Desça devagar. Alterne as pernas ou complete um lado por vez."],["Evite impulsionar com a perna de baixo."]],"sumo":[["Fique com os pés bem afastados e as pontas viradas para fora.","Segure o peso entre as pernas ou apoie a barra nas costas.","Desça mantendo o tronco ereto e os joelhos apontando para os pés.","Suba contraindo glúteos e parte interna das coxas."],["Os joelhos não devem cair para dentro."]],"sissy":[["Fique em pé segurando um apoio, com os calcanhares elevados.","Incline o corpo para trás em linha reta enquanto dobra os joelhos à frente.","Desça até onde controlar e volte estendendo os joelhos."],["Exercício avançado para o quadríceps; comece sem carga."]],"pistol":[["Fique em uma perna só, com a outra estendida à frente.","Desça devagar dobrando o joelho de apoio, braços à frente para equilibrar.","Desça o máximo que controlar e suba sem apoiar a outra perna."],["Use um apoio ou uma caixa atrás para aprender."]],"salto":[["Fique com os pés na largura do quadril.","Agache rapidamente e salte com força, usando os braços.","Aterrisse com os joelhos levemente dobrados para amortecer.","Reposicione-se e repita."],["Aterrisse suave, sem travar os joelhos."]],"isometrico":[["Apoie as costas em uma parede.","Deslize até os joelhos formarem cerca de 90°.","Mantenha a posição pelo tempo definido."],["Joelhos alinhados com os tornozelos."]],"hipthrust":[["Apoie a parte de cima das costas em um banco e posicione o peso sobre o quadril.","Pés no chão na largura do quadril, joelhos dobrados.","Empurre o quadril para cima até o corpo ficar reto dos ombros aos joelhos.","Contraia os glúteos no topo e desça devagar."],["Queixo levemente para baixo e costelas fechadas.","No topo, as canelas ficam verticais."]],"ponte":[["Deite de costas com os joelhos dobrados e os pés no chão.","Empurre o quadril para cima contraindo os glúteos.","Segure no topo e desça devagar."],["Não arqueie a lombar no topo; quem sobe é o quadril."]],"coicegluteo":[["Posicione-se na máquina, no cabo ou em quatro apoios no chão.","Com o abdômen contraído, leve uma perna para trás e para cima.","Contraia o glúteo no final do movimento.","Volte devagar. Complete as repetições e troque de perna."],["Não arqueie a lombar para subir mais."]],"abdutora":[["Sente na máquina com as costas apoiadas e as almofadas por fora dos joelhos.","Abra as pernas o máximo possível.","Volte devagar sem deixar o peso bater."],["Inclinar levemente o tronco à frente foca mais nos glúteos."]],"adutora":[["Sente na máquina com as almofadas por dentro dos joelhos.","Feche as pernas contraindo a parte interna das coxas.","Volte devagar até sentir o alongamento."],["Controle a abertura; não force além do confortável."]],"caminhadalat":[["Coloque o elástico acima dos joelhos ou nos tornozelos.","Fique em semiagachamento.","Dê passos laterais mantendo a tensão no elástico.","Faça o mesmo número de passos para o outro lado."],["Não deixe os joelhos caírem para dentro."]],"panturrilha":[["Posicione a parte da frente dos pés na plataforma, calcanhares livres.","Desça os calcanhares até sentir o alongamento.","Suba na ponta dos pés o máximo possível.","Segure um instante no topo e desça devagar."],["Use amplitude completa.","Não dobre os joelhos para ajudar."]],"panturrilhasent":[["Sente na máquina com o apoio sobre as coxas, perto dos joelhos.","Apoie a parte da frente dos pés na plataforma.","Desça os calcanhares e depois suba o máximo possível.","Segure no topo e desça devagar."],["Com os joelhos dobrados, o foco é o sóleo."]],"nordica":[["Ajoelhe com os tornozelos presos por um apoio ou parceiro.","Com o corpo reto dos joelhos à cabeça, incline-se à frente devagar.","Desça o máximo que controlar e amorteça com as mãos.","Volte usando os posteriores (ou empurre levemente com as mãos)."],["Exercício intenso; comece com poucas repetições."]],"glutehamraise":[["Posicione-se no aparelho com os pés presos e os joelhos logo atrás da almofada.","Desça o tronco até ficar paralelo ao chão.","Suba dobrando os joelhos e contraindo glúteos e posteriores."],["Mantenha o corpo em linha reta dos joelhos à cabeça."]],"crunch":[["Deite de costas com os joelhos dobrados e os pés no chão.","Coloque as mãos ao lado da cabeça ou cruzadas no peito.","Contraia o abdômen tirando os ombros do chão.","Desça devagar."],["Não puxe o pescoço com as mãos."]],"situp":[["Deite de costas com os joelhos dobrados e os pés presos ou firmes no chão.","Suba o tronco inteiro até ficar sentado.","Desça devagar até as costas encostarem no chão."],["Expire na subida."]],"crunchmaq":[["Sente na máquina e segure as alças com os pés presos.","Contraia o abdômen trazendo o tronco para a frente e para baixo.","Volte devagar."],["O movimento é de enrolar a coluna, não de dobrar o quadril."]],"abpolia":[["Ajoelhe de frente para a polia alta segurando a corda ao lado da cabeça.","Enrole o tronco trazendo os cotovelos em direção aos joelhos.","Volte devagar, sem mover o quadril."],["O quadril fica parado; quem trabalha é o abdômen."]],"declinado":[["Prenda os pés no banco declinado e deite.","Suba o tronco contraindo o abdômen.","Desça devagar até perto do banco."],["Segure uma anilha no peito para aumentar a carga."]],"infra":[["Deite de costas com as pernas dobradas e as mãos ao lado do corpo.","Contraia o abdômen trazendo os joelhos em direção ao peito e tirando o quadril do chão.","Desça devagar."],["Evite usar impulso das pernas."]],"elevsusp":[["Fique pendurado na barra com os braços estendidos.","Contraia o abdômen e suba as pernas (ou os joelhos) até a altura do quadril ou mais.","Desça devagar, sem balançar."],["Joelhos dobrados é a versão mais fácil."]],"elevparalelas":[["Apoie os antebraços na cadeira romana (ou segure as paralelas) com as costas no encosto.","Suba as pernas ou os joelhos contraindo o abdômen.","Desça devagar sem balançar."],["Não use impulso."]],"elevdeitado":[["Deite de costas com as pernas estendidas e as mãos sob o quadril.","Suba as pernas até ficarem verticais.","Desça devagar sem encostar os pés no chão."],["Mantenha a lombar colada no chão."]],"prancha":[["Apoie os antebraços no chão, cotovelos abaixo dos ombros.","Estenda as pernas e apoie as pontas dos pés.","Mantenha o corpo reto, contraindo abdômen e glúteos.","Segure pelo tempo definido, respirando normalmente."],["Não deixe o quadril cair nem subir."]],"pranchalat":[["Deite de lado e apoie o antebraço no chão, cotovelo abaixo do ombro.","Levante o quadril até o corpo ficar em linha reta.","Segure pelo tempo definido e troque de lado."],["Mantenha o quadril alto o tempo todo."]],"pranchainv":[["Sente com as pernas estendidas e apoie as mãos atrás do quadril.","Levante o quadril até o corpo ficar reto dos ombros aos calcanhares.","Segure pelo tempo definido."],["Contraia glúteos para manter o quadril alto."]],"roda":[["Ajoelhe e segure a roda abdominal à frente.","Role para a frente estendendo o corpo, sem deixar a lombar afundar.","Vá até onde controlar e volte contraindo o abdômen."],["Comece com amplitude curta."]],"giro":[["Sente com os joelhos dobrados e incline o tronco para trás.","Tire os pés do chão (ou mantenha apoiados para facilitar).","Gire o tronco de um lado para o outro levando as mãos (ou o peso) ao lado do quadril."],["Gire o tronco, não só os braços."]],"bicicleta":[["Deite de costas com as mãos ao lado da cabeça e as pernas elevadas.","Leve o cotovelo em direção ao joelho oposto enquanto estende a outra perna.","Alterne os lados de forma contínua e controlada."],["Não puxe o pescoço."]],"deadbug":[["Deite de costas com os braços estendidos para o teto e os joelhos dobrados a 90°.","Estenda um braço para trás e a perna oposta à frente, sem tirar a lombar do chão.","Volte e repita para o outro lado."],["A lombar deve ficar colada no chão o tempo todo."]],"canivete":[["Deite de costas com braços e pernas estendidos.","Suba braços e pernas ao mesmo tempo, tentando tocar os pés.","Desça devagar."],["Mantenha pernas e braços estendidos."]],"pallof":[["Fique de lado para a polia com a alça na altura do peito.","Estenda os braços à frente do peito resistindo à rotação.","Segure um instante e volte as mãos ao peito.","Troque de lado ao final."],["O tronco não pode girar: é um exercício anti-rotação."]],"lenhador":[["Fique de lado para a polia e segure a alça com as duas mãos.","Gire o tronco puxando a alça em diagonal, de cima para baixo ou de baixo para cima.","Volte devagar. Troque de lado ao final."],["O giro vem do tronco e do quadril, com braços quase retos."]],"hollow":[["Deite de costas e tire ombros e pernas do chão, braços estendidos acima da cabeça.","Mantenha a lombar colada no chão.","Segure a posição ou balance levemente para a frente e para trás."],["Se a lombar descolar, dobre os joelhos."]],"lsit":[["Apoie as mãos no chão, paralelas ou barras com os braços estendidos.","Levante as pernas estendidas à frente até formar um L.","Segure pelo tempo definido."],["Com joelhos dobrados fica mais fácil."]],"tesoura":[["Deite de costas com as mãos sob o quadril.","Tire as pernas do chão e alterne-as para cima e para baixo (ou cruzando).","Mantenha a lombar colada no chão."],["Movimentos curtos e controlados."]],"calcanhar":[["Deite de costas com os joelhos dobrados e os pés no chão.","Tire os ombros do chão e leve a mão a tocar o calcanhar do mesmo lado.","Alterne os lados."],["Trabalha os oblíquos; mantenha os ombros elevados."]],"toquepes":[["Deite de costas com as pernas estendidas para o teto.","Suba o tronco levando as mãos em direção aos pés.","Desça devagar."],["As pernas ficam paradas e verticais."]],"flexlateral":[["Fique em pé segurando o peso em uma mão, ao lado do corpo.","Incline o tronco para o lado do peso.","Volte à posição em pé contraindo o lado oposto. Troque de lado ao final."],["Não gire o tronco; o movimento é só lateral."]],"obliquo":[["Deite de lado ou de costas com os joelhos dobrados.","Contraia o abdômen trazendo o ombro em direção ao quadril oposto.","Desça devagar e alterne os lados."],["Não puxe o pescoço com as mãos."]],"rotacao":[["Sente na máquina de rotação com as pernas presas.","Gire o tronco contra a resistência de forma controlada.","Volte devagar e faça o outro lado."],["Use carga moderada e amplitude confortável."]],"escalador":[["Fique em posição de flexão com os braços estendidos.","Traga um joelho em direção ao peito e volte.","Alterne as pernas rapidamente, mantendo o quadril baixo."],["Mantenha as mãos abaixo dos ombros."]],"landmine180":[["Segure a ponta da barra landmine com os braços estendidos à frente do peito.","Gire o tronco levando a barra para um lado, perto do quadril.","Passe a barra pela frente até o outro lado."],["O quadril acompanha o giro; os braços ficam estendidos."]],"swing":[["Fique com os pés um pouco mais abertos que os ombros e o kettlebell à frente.","Empurre o quadril para trás e leve o kettlebell entre as pernas.","Estenda o quadril com força, projetando o kettlebell até a altura do peito.","Deixe-o descer e repita o movimento de forma contínua."],["O impulso vem do quadril, não dos braços.","Coluna neutra o tempo todo."]],"clean":[["Comece com a barra no chão (ou na altura das coxas, na versão hang), como no levantamento terra.","Estenda o quadril de forma explosiva, puxando a barra rente ao corpo.","Encaixe rapidamente por baixo da barra, recebendo-a na frente dos ombros com os cotovelos altos.","Fique em pé com a barra apoiada."],["Movimento técnico: aprenda com carga leve ou com um treinador."]],"arranco":[["Comece com o peso no chão ou entre as pernas.","Estenda o quadril de forma explosiva e puxe o peso para cima, rente ao corpo.","Encaixe por baixo, recebendo o peso acima da cabeça com o braço estendido.","Fique em pé e desça o peso de forma controlada."],["Exige técnica; comece leve."]],"thruster":[["Segure o peso na frente dos ombros.","Faça um agachamento completo.","Ao subir, use o impulso para empurrar o peso acima da cabeça em um movimento contínuo.","Volte o peso aos ombros e repita."],["Muito exigente; mantenha o ritmo constante."]],"pushpress":[["Segure o peso na frente dos ombros com os pés na largura do quadril.","Dobre levemente os joelhos e estenda as pernas com força.","Use o impulso para empurrar o peso acima da cabeça.","Desça o peso de volta aos ombros."],["O mergulho das pernas é curto e rápido."]],"turco":[["Deite segurando o kettlebell com o braço estendido acima do peito.","Apoie-se no cotovelo e depois na mão oposta, subindo o tronco.","Eleve o quadril, passe a perna por baixo e fique ajoelhado.","Fique em pé e desfaça o caminho até deitar novamente."],["Olhe sempre para o kettlebell; vá devagar."]],"fazendeiro":[["Segure um peso pesado em cada mão, ao lado do corpo.","Fique ereto com os ombros para trás e o abdômen contraído.","Caminhe com passos curtos e firmes pela distância ou tempo definido."],["Não deixe os ombros caírem para a frente."]],"burpee":[["Fique em pé e agache apoiando as mãos no chão.","Salte os pés para trás até a posição de flexão.","Faça uma flexão (opcional) e salte os pés de volta às mãos.","Salte para cima com os braços acima da cabeça."],["Mantenha o ritmo constante."]],"polichinelo":[["Fique em pé com os pés juntos e os braços ao lado do corpo.","Salte abrindo as pernas e levando os braços acima da cabeça.","Salte de volta à posição inicial e repita."],["Aterrisse na ponta dos pés."]],"urso":[["Fique em quatro apoios com os joelhos elevados alguns centímetros do chão.","Caminhe para a frente movendo mão e pé opostos juntos.","Mantenha as costas retas e o quadril baixo."],["Passos curtos e controlados."]],"halo":[["Segure o kettlebell de cabeça para baixo pela alça, na frente do peito.","Circule o peso ao redor da cabeça, passando perto da nuca.","Volte à frente e repita, alternando o sentido."],["Mantenha o abdômen contraído e o tronco parado."]],"treno":[["Segure as alças do trenó (ou prenda o colete) com o corpo inclinado.","Empurre ou puxe com passos curtos e fortes.","Mantenha o tronco firme e a coluna neutra."],["A distância e a carga definem a intensidade."]],"bolamed":[["Segure a bola medicinal com as duas mãos.","Leve a bola acima da cabeça estendendo o corpo.","Arremesse a bola com força contra o chão ou a parede.","Recupere a bola e repita."],["Use o corpo inteiro, não só os braços."]],"cordanaval":[["Segure uma ponta da corda em cada mão em semiagachamento.","Faça ondas alternando os braços (ou simultâneas) de forma rápida.","Mantenha o ritmo pelo tempo definido."],["Joelhos levemente dobrados e abdômen firme."]],"muscleup":[["Segure a barra ou as argolas com pegada firme.","Faça uma barra fixa explosiva levando o peito acima da barra.","Gire os punhos e transicione para cima da barra.","Termine empurrando como em uma paralela até estender os braços."],["Exercício avançado; domine barra e paralela antes."]],"paradamao":[["Apoie as mãos no chão perto de uma parede, na largura dos ombros.","Suba as pernas até ficar de cabeça para baixo com o corpo reto.","Mantenha a posição pelo tempo definido (ou desça a cabeça em direção ao chão e empurre, na versão flexão)."],["Comece com apoio na parede."]],"frontlever":[["Fique pendurado na barra com os braços estendidos.","Puxe a barra para baixo com as costas e eleve o corpo até ficar horizontal.","Segure (sustentação) ou suba e desça de forma controlada (elevação)."],["Versões com joelhos dobrados facilitam o aprendizado."]],"pescoco":[["Deite no banco com a cabeça para fora da borda.","Mova a cabeça devagar em toda a amplitude confortável (para cima e para baixo).","Se usar carga, apoie uma anilha leve na testa ou na nuca, com uma toalha."],["Use carga bem leve e movimentos lentos."]],"cardio":[["Comece com 3 a 5 minutos em ritmo leve para aquecer.","Mantenha o ritmo planejado, controlando a respiração.","Termine com alguns minutos em ritmo leve para desacelerar."],["Registre tempo e, se tiver, distância para acompanhar a evolução."]],"mobilidade":[["Faça os movimentos devagar, respirando de forma profunda.","Mantenha cada posição pelo tempo indicado, sem dor.","Avance a amplitude aos poucos."],["Desconforto leve é normal; dor, não."]],"pescoco_iso":[["Sente ou fique em pé com a coluna ereta.","Faça força com a cabeça contra a mão, sem deixar a cabeça se mover.","Segure alguns segundos e troque a direção."],["Use pouca força no começo."]]};
const EQ_TIPS={"Barra":"Registre o peso total: barra + anilhas dos dois lados. Uma barra olímpica comum pesa 20 kg.","Halter":"Registre o peso de um halter só, mesmo usando um em cada mão.","Kettlebell":"Registre o peso de um kettlebell. Se usar dois, registre o de um só.","Máquina":"Registre o peso indicado na máquina ou na placa do pino.","Cabo":"Registre o peso marcado na torre de polia.","Smith":"Registre só as anilhas colocadas; a barra do Smith costuma ser contrapesada.","Anilha":"Registre o peso total das anilhas usadas.","Peso corporal":"Deixe o kg em branco sem carga extra. Com colete ou anilha, registre só o peso extra.","Elástico":"Anote a cor ou a resistência do elástico nas notas do exercício.","Fita de suspensão":"Quanto mais inclinado o corpo, mais difícil. Anote a posição nas notas."};
